window.I18N["hu"].t_stack_disk_d = "Közvetlen NTFS Master File Table felsorolás rendszergazdaként, párhuzamos <code>FindFirstFileExW</code> tartalékkal, amely egyetlen renderelési menetben kirajzolt négyzetesített fatérképet táplál";
window.I18N["pl"].t_stack_disk_d = "Bezpośrednie wyliczanie tablicy MFT systemu NTFS przy podniesionych uprawnieniach, z równoległym rozwiązaniem awaryjnym <code>FindFirstFileExW</code>, zasilające kwadratową mapę drzewa rysowaną w jednym przebiegu";
window.I18N["es"].t_stack_disk_d = "Enumeración directa de la Master File Table de NTFS con permisos elevados, con un respaldo paralelo <code>FindFirstFileExW</code>, que alimenta un treemap cuadrificado dibujado en una sola pasada";
window.I18N["de"].t_stack_disk_d = "Direkte Enumeration der NTFS Master File Table mit erhöhten Rechten, mit einem parallelen <code>FindFirstFileExW</code>-Fallback, der eine in einem einzigen Renderdurchgang gezeichnete Squarified-Treemap speist";
window.I18N["fr"].t_stack_disk_d = "Énumération directe de la Master File Table NTFS en mode élevé, avec un repli parallèle <code>FindFirstFileExW</code>, qui alimente une treemap squarifiée dessinée en une seule passe";
window.I18N["tr"].t_stack_disk_d = "Yükseltilmiş yetkiyle doğrudan NTFS Master File Table sayımı, paralel <code>FindFirstFileExW</code> yedeğiyle, tek bir çizim geçişinde çizilen kareleştirilmiş ağaç haritasını besler";
window.I18N["zh-cn"].t_stack_disk_d = "提权时直接枚举 NTFS 主文件表，并以并行的 <code>FindFirstFileExW</code> 作为回退，为一次渲染绘制的平方化树图提供数据";
window.I18N["zh"].t_stack_disk_d = "提權時直接列舉 NTFS 主檔案表，並以平行的 <code>FindFirstFileExW</code> 作為後備，為一次算繪繪製的平方化樹狀圖提供資料";
window.I18N["cs"].t_stack_disk_d = "Přímý výčet NTFS Master File Table při zvýšených oprávněních, s paralelní zálohou <code>FindFirstFileExW</code>, která napájí čtvercovanou stromovou mapu vykreslenou v jednom průchodu";
window.I18N["ja"].t_stack_disk_d = "昇格時に NTFS マスターファイルテーブルを直接列挙し、並列の <code>FindFirstFileExW</code> をフォールバックとして、1 回の描画パスで描かれるスクエリファイド ツリーマップにデータを供給します";
window.I18N["bn"].t_stack_disk_d = "উন্নীত অধিকারে NTFS মাস্টার ফাইল টেবিল সরাসরি গণনা করে, সমান্তরাল <code>FindFirstFileExW</code> ফলব্যাক সহ, যা এক পাসে আঁকা স্কোয়ারিফায়েড ট্রিম্যাপে ডেটা জোগায়";
window.I18N["pl"].h_ks_h = "Ta sama tabela, którą aplikacja pokazuje pod F1<span class=\"chev\">&#9656;</span>";
window.I18N["es"].h_ks_h = "La misma tabla que la app muestra con F1<span class=\"chev\">&#9656;</span>";
window.I18N["de"].h_ks_h = "Dieselbe Tabelle, die die App auf F1 zeigt<span class=\"chev\">&#9656;</span>";
