  "cm_log": "// jeder Name, der auf .log endet",
  "cm_xlsx": "// report_, dann beliebig, dann .xlsx",
  "cm_tmp1": "// ein Zeichen, dann .tmp",
  "cm_tmp2": "// genau ein Zeichen, dann .tmp",
