  "hx_090": "Sledování výkonu<span class=\"kbd\">F11</span><span class=\"chev\">&#9656;</span>",
  "hx_094": "Analyzátor úložiště<span class=\"kbd\">F4 / Ctrl+F4</span><span class=\"chev\">&#9656;</span>",
